module bookland_ordering (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [3:0] m,\n    input wire [3:0] word_len [0:7],\n    input wire [31:0] word_data [0:7],\n    output reg yes,\n    output reg [3:0] k,\n    output reg [7:0] letters_out,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] S_IDLE        = 3'd0;\n    localparam [2:0] S_CHECK_MASK  = 3'd1;\n    localparam [2:0] S_CHECK_PAIR  = 3'd2;\n    localparam [2:0] S_NEXT_MASK   = 3'd3;\n    localparam [2:0] S_FOUND       = 3'd4;\n    localparam [2:0] S_NO_RESULT   = 3'd5;\n    localparam [2:0] S_OUTPUT      = 3'd6;\n\n    reg [2:0] state;\n    reg [2:0] next_state;\n    reg [2:0] pair_idx;\n    reg [7:0] current_mask;\n    wire valid;\n\n    // Function to count set bits\n    function [3:0] count_bits(input [7:0] mask);\n        count_bits = 4'd0;\n        for (integer i = 0; i < 8; i = i + 1) begin\n            if (mask[i]) count_bits = count_bits + 1'b1;\n        end\n    endfunction\n\n    // Assign current pair's words\n    wire [3:0] w1_len  = word_len[pair_idx];\n    wire [3:0] w2_len  = word_len[pair_idx + 1];\n    wire [31:0] w1_data = word_data[pair_idx];\n    wire [31:0] w2_data = word_data[pair_idx + 1];\n\n    // Internal comparator logic\n    reg valid_int;\n    always @(*) begin\n        valid_int = 1'b1;\n        reg [3:0] min_len = (w1_len < w2_len) ? w1_len : w2_len;\n        \n        for (integer j = 0; j < 8; j = j + 1) begin\n            if (j < min_len) begin\n                reg [3:0] char1 = w1_data[j*4 +: 4];\n                reg [3:0] char2 = w2_data[j*4 +: 4];\n                reg cap1 = char1 != 0 ? current_mask[char1 - 1] : 1'b0;\n                reg cap2 = char2 != 0 ? current_mask[char2 - 1] : 1'b0;\n                \n                if (char1 != char2) begin\n                    if ((cap1 && !cap2) || (!cap1 && !cap2 && char1 < char2)) begin\n                        valid_int = 1'b1;\n                    end else if ((!cap1 && cap2) || (!cap1 && !cap2 && char1 > char2)) begin\n                        valid_int = 1'b0;\n                    end\n                    break;\n                end\n            end\n        end\n        \n        if (valid_int && w1_len > w2_len) valid_int = 1'b0;\n    end\n    assign valid = (pair_idx >= n-1) ? 1'b1 : valid_int;\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state       <= S_IDLE;\n            yes         <= 1'b0;\n            k           <= 4'd0;\n            letters_out <= 8'd0;\n            done        <= 1'b0;\n            pair_idx    <= 3'd0;\n            current_mask <= 8'd0;\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        if (n <= 4'd1) begin\n                            yes <= 1'b1;\n                            letters_out <= 8'd0;\n                            k <= 4'd0;\n                            state <= S_OUTPUT;\n                        end else begin\n                            current_mask <= 8'd0;\n                            state <= S_CHECK_MASK;\n                        end\n                    end\n                end\n                \n                S_CHECK_MASK: begin\n                    pair_idx <= 3'd0;\n                    state <= S_CHECK_PAIR;\n                end\n                \n                S_CHECK_PAIR: begin\n                    if (pair_idx < n-1) begin\n                        if (!valid) begin\n                            state <= S_NEXT_MASK;\n                        end else begin\n                            pair_idx <= pair_idx + 1'b1;\n                        end\n                    end else begin\n                        state <= S_FOUND;\n                    end\n                end\n                \n                S_NEXT_MASK: begin\n                    if (current_mask == 8'd255 || current_mask >= (8'd1 << m) - 1) begin\n                        state <= S_NO_RESULT;\n                    end else begin\n                        current_mask <= current_mask + 1'b1;\n                        state <= S_CHECK_MASK;\n                    end\n                end\n                \n                S_FOUND: begin\n                    yes <= 1'b1;\n                    k <= count_bits(current_mask);\n                    letters_out <= current_mask;\n                    state <= S_OUTPUT;\n                end\n                \n                S_NO_RESULT: begin\n                    yes <= 1'b0;\n                    k <= 4'd0;\n                    letters_out <= 8'd0;\n                    state <= S_OUTPUT;\n                end\n                \n                S_OUTPUT: begin\n                    done <= 1'b1;\n                    if (!start) state <= S_IDLE;\n                end\n                \n                default: state <= S_IDLE;\n            endcase\n        end\n    end\nendmodule